  const t = text => text;
  const markup = raw => raw;
  const html = (parts, ...values) => parts.reduce((result, part, index) => result + markup(part) + (values[index] ?? ''), '');
  const formatValue = value => value && typeof value==='object' ? Object.entries(value).map(([key,item])=>key+': '+item).join('; ') : (value||'—');
  const labels = Object.fromEntries(Object.entries(GMPP.labels).map(([key,value])=>[key,t(value)]));
  const stateNames = {draft:wp.i18n.__("Draft", 'giuliomax-product-passport'),published:wp.i18n.__("Published", 'giuliomax-product-passport'),archived:wp.i18n.__("Discontinued", 'giuliomax-product-passport'),queued:wp.i18n.__("Queued", 'giuliomax-product-passport'),running:wp.i18n.__("Running", 'giuliomax-product-passport'),done:wp.i18n.__("Completed", 'giuliomax-product-passport'),cancelled:wp.i18n.__("Cancelled", 'giuliomax-product-passport')};
